<template><main class="signup-page"><form class="card" @submit.prevent="submit"><router-link class="brand" to="/blugbugs"><img src="/brand_logo.svg" alt="Blugbug"></router-link><span class="eyebrow">Create account</span><h1>Join the conversation.</h1><p class="intro">Create your Blugbug profile. You can browse as a guest at any time.</p><label>Full name<input v-model="fullName" autocomplete="name" maxlength="100" required></label><label>Blugbug handle<div class="handle"><span>@</span><input v-model="handle" autocomplete="username" maxlength="40" pattern="[A-Za-z0-9._-]{2,40}" required></div></label><label>Email<input v-model="email" type="email" autocomplete="email" required></label><label>Password<input v-model="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirm password<input v-model="confirmPassword" type="password" autocomplete="new-password" minlength="8" required></label><label class="terms"><input v-model="accepted" type="checkbox" required><span>I agree to the <router-link to="/terms-and-conditions">terms and conditions</router-link>.</span></label><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p><button class="primary" :disabled="loading||Boolean(success)">{{ loading?'Creating account…':'Create account' }}</button><router-link class="login" :to="loginTarget">Already have an account? Sign in</router-link><button class="guest" type="button" @click="continueAsGuest">Continue as guest</button></form></main></template>
<script setup lang="ts">import{computed,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{signup}from'../api/auth';import{authStore}from'../stores/auth';const route=useRoute(),router=useRouter(),fullName=ref(''),handle=ref(''),email=ref(''),password=ref(''),confirmPassword=ref(''),accepted=ref(false),loading=ref(false),error=ref(''),success=ref('');const redirect=computed(()=>typeof route.query.redirect==='string'?route.query.redirect:'/home'),loginTarget=computed(()=>`/login?redirect=${encodeURIComponent(redirect.value)}`);const continueAsGuest=()=>router.push('/blugbugs');const submit=async()=>{error.value='';if(password.value!==confirmPassword.value){error.value='Passwords do not match.';return}loading.value=true;try{const result=await signup(fullName.value,handle.value,email.value,password.value);if(result.hasSession){await authStore.loginWithSupabase();await router.push(redirect.value)}else success.value='Account created. Check your email to confirm it, then sign in.'}catch(e){error.value=e instanceof Error?e.message:'Could not create your account.'}finally{loading.value=false}};</script>
<style scoped>.signup-page{min-height:100vh;display:grid;place-items:center;padding:32px;background:var(--surface)}.card{width:min(520px,100%);display:grid;gap:14px;padding:38px;border:1px solid var(--line);border-radius:24px;background:var(--panel);box-shadow:0 18px 50px rgba(55,43,29,.12)}.brand img{width:150px}.card h1{margin:0;font:700 2.6rem/1 Georgia,serif;color:var(--text)}.intro{margin:0 0 7px;color:var(--muted);line-height:1.55}.card>label:not(.terms){display:grid;gap:7px;color:var(--text);font-size:.78rem;font-weight:800}.card input{box-sizing:border-box;width:100%;padding:12px 13px;border:1px solid var(--line);border-radius:10px;background:var(--input);color:var(--text);font:inherit}.handle{display:flex;align-items:center;border:1px solid var(--line);border-radius:10px;background:var(--input)}.handle span{padding-left:13px;color:var(--muted)}.handle input{border:0;background:transparent}.terms{display:flex;align-items:flex-start;gap:9px;color:var(--muted);font-size:.8rem}.terms input{width:auto;margin-top:2px}.terms a,.login{color:var(--orange);font-weight:800}.primary{padding:13px;border:0;border-radius:11px;background:var(--orange);color:#fff;font-weight:900;cursor:pointer}.login,.guest{text-align:center}.guest{border:0;background:none;color:var(--muted);font-weight:800;cursor:pointer}.error{margin:0;color:#b91f24}.success{margin:0;padding:11px;border-radius:9px;background:#e5f4e8;color:#205b2c}@media(max-width:520px){.signup-page{padding:0}.card{min-height:100vh;border:0;border-radius:0;padding:28px 22px;box-shadow:none}}</style>
